static func goal_next(goal: Dictionary) -> String:
	return "" if goal.next.is_empty() \
		else TranslationServer.translate("CHEQUE_NEXT").format({"step": goal_step(goal.next)})


## A step's words; a revenue step names its bar ("Aylık gelir $2.5K").
static func goal_step(step: Dictionary) -> String:
	return TranslationServer.translate(step.text_key).format({"bar": Fmt.money_chip(int(step.get("target", 0)))})


# --- Items ---------------------------------------------------------------------------------------

## A card as an item: its view in the live language with the names it kept, its sender and topic; `at` is when it
## reached the player (MailClock), -1 for none.
static func card_item(id: String, event_id: String, ctx: Dictionary, names: Dictionary, day: int, at := -1) -> Dictionary:
	var card: Dictionary = EventGate.catalogue_card(event_id)
	var ev: GameEvent = EventGate.render(event_id, ctx, names)
	var from: Dictionary = card_sender(card, ctx, names)
	return {"id": id, "event_id": event_id, "ctx": ctx, "names": names, "event": ev, "day": day, "at": at,
		"unread": false, "waiting": false, "sender": from, "subject": ev.title, "line": first_line(ev.body_text),
		"paper": String(card.get("class", "")) == "paper",
		"topic": "EVENT_TAG_MENTOR" if from.kind == "frank" else String(EvChips.source_tag(ev, String(card.get("category", ""))).key)}


static func _paper_item(p: Dictionary) -> Dictionary:
	var it := card_item("paper:" + String(p.id), String(p.event_id), p.context, p.names, int(p.admitted_day), int(p.at))
	it.merge({"kind": "paper", "key": String(p.id), "waiting": true, "unread": not bool(p.opened),
		"weeks_left": int(p.weeks_left), "expiring": bool(p.expiring)}, true)
	return it

		ladder.add_child(row)
	var spot := MarginContainer.new()
	spot.add_theme_constant_override("margin_top", UiTokens.SPACE_L)
	col.add_child(spot)
	var goal := UiFactory.D_card(spot)
	goal.add_theme_constant_override("separation", UiTokens.SPACE_XS)
	goal.add_child(SprintUiShared.label(Fmt.upper(tr("PER_PHASE_GOAL")), &"KeyLabel"))
	# An open goal list is the goal, as Finans counts it: "Frank'in çeki · 2/5" and its next step.
	var goal_list: Dictionary = ChequeRead.summary()
	if goal_list.is_empty():
		goal.add_child(SprintUiShared.label(tr(GOAL_KEYS[GameState.phase]), &"SubjectStrong"))
	else:
		goal.add_child(SprintUiShared.label(INBOX.goal_head(goal_list), &"SubjectStrong"))
		if not goal_list.next.is_empty():
			goal.add_child(SprintUiShared.prose(INBOX.goal_next(goal_list), &"BodyLabel"))
	col.add_child(_above(_section("PER_NET_WORTH"), UiTokens.SPACE_3XL))
	var share := SprintUiShared.column(UiTokens.SPACE_M)
	FinanceOzetView.cap_table(share)
	var valuation: float = GameState.get_valuation_m()
	if valuation > 0.0:
		share.add_child(SprintUiShared.label(tr("PER_VALUATION_ROW").format(
			{"value": Fmt.money_market(valuation)}), &"MetaText"))
	else:
		share.add_child(SprintUiShared.prose(tr("PER_NO_VALUATION"), &"Caption"))
	col.add_child(_above(share, UiTokens.SPACE_M))
	return col

